/// A verb form: which cell of its conjugation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Cell {
    /// A finite form (`tú` for the second person singular; [`vos`] gives the voseo forms). A pronominal verb's form comes without its pronoun (`quejarse` → `quejo`, as in `me quejo`).
    Form(crate::Tense, crate::Person, crate::Number),
    /// The second person singular with `vos` (Argentina, Uruguay, Central America): `vos hacés`, `que vos hagás`, `hacé`. In the other tenses `vos` takes the `tú` form.
    Vos(crate::Mood),
    /// The affirmative imperative (`haz`, `haga`, `hagamos`, `haced`, `hagan`).
    Imperative(crate::Addressee),
    /// The negative imperative, written after `no` (`no hagas`).
    NegativeImperative(crate::Addressee),
    /// The infinitive.
    Infinitive,
    /// The gerund (`haciendo`).
    Gerund,
    /// The past participle, agreeing in gender and number (`hecho`, `hechas`).
    Participle(crate::Gender, crate::Number),
}

